"""M2 champion = the Python module generated by the R->Python Migration Agent (see src/common/champion.py).

Module-level helpers keep the API used by validate.py / fairness.py / parity.py / monitor.py.
"""
from __future__ import annotations

from agent.validators.champion import ROOT, Champion, Fit  # noqa: F401

_C = Champion("m2_taiwan", id_column="ID")
M = _C.m                                    # paths + config + thresholds for M2


def cfg() -> dict:
    return _C.cfg


def output_dir():
    return _C.output_dir


def module_path():
    return _C.module_path


def reference_dir():
    return _C.reference_dir


def data_path():
    return _C.data_path


def module():
    return _C.module


def provenance() -> dict:
    return _C.provenance()


def load():
    return _C.load()


def fit(train) -> Fit:
    return _C.fit(train)
